["hud_heist_kenaz_s_02_hl"] = "Golden Grin planlarını edin",
["hud_heist_kenaz_s_02b"] = "Bilgi işlem bölümünde bir tarayıcı bul. Planları tarayıp Bain'e faksla.",
["hud_heist_kenaz_s_02b_hl"] = "Planları tara ve Bain’e faksla",
["hud_heist_kenaz_s_03"] = "O konuk odasında kimin kaldığını bulmalıyız. Konuk listesini USB belleğe indir. Listeyi kumarhane resepsiyonundaki bir terminalden alabilirsin.",
["hud_heist_kenaz_s_03_hl"] = "Konuk listesini indir",
["hud_heist_kenaz_s_03a"] = "Bain otelin konuk listesini istiyor. Listeyi USB belleğe kopyalayıp verileri ona yükle. USB bellek bulmak için en iyi yer bilişim odası.",
["hud_heist_kenaz_s_03a_hl"] = "Bir bellek bul ve al",
["hud_heist_kenaz_s_03b"] = "İnternete bağlı bir bilgisayar bul. USB belleği takıp konuk listesini Bain’e yükle.",
["hud_heist_kenaz_s_03b_hl"] = "Konuk listesini yükle",
["hud_heist_kenaz_s_04"] = "Bain’in gönderdiği resme bakıp bu konuğun tam yerini bul. Kendisi bir kumar makinesi bağımlısı; muhtemelen oynuyordur.",
["hud_heist_kenaz_s_04_hl"] = "Kumar Salonundaki konuğu bul",
["hud_heist_kenaz_s_05a"] = "Konuğun şişesi boş. İçine zehir katılmış yenisini getir. Kumarhanedeki barlarda şişeleri ara, içine zehir koy. Sevdiği içkiyi almayı unutma.",
["hud_heist_kenaz_s_05a_hl"] = "Doğru şişeyi bulup zehir kat",
["hud_heist_kenaz_s_06"] = "Konuğa zehirli içkiyi doldur. Cimrilik etme. Herkesin eğlendiği Vegas’tayız; bardağı doldur.",
["hud_heist_kenaz_s_06_hl"] = "Konuğa zehirli içkiyi ver",
["hud_heist_kenaz_s_07"] = "İçecek artık zehirli. Kimya ve biyolojinin işini yapmasını bekle. Tuvalete koştuğunda peşinden git. Onunla kuytu bir yerde ilgilen.",
["hud_heist_kenaz_s_07_hl"] = "Zehrin etki etmesini bekle",
["hud_heist_kenaz_s_08"] = "Konuk Anahtar Kartını az önce düşürdü. Onu al. Odasına girmek için kullanabilirsin.",
["hud_heist_kenaz_s_08_hl"] = "Otel odasının Anahtar Kartını al",
["hud_heist_kenaz_s_09"] = "Anahtar Kartıyla otel odasına gir. Havalandırmayı bulup kanala uyutucu gaz pompalamaya başla. Bu, Güvenlik Merkezindeki muhafızları uyutacak.",
["hud_heist_kenaz_s_09_hl"] = "Havalandırmaya uyutucu gaz pompala",
["hud_heist_kosugi"] = "Depodan çalabildiğin kadar çal. Sessiz kal.",
["hud_heist_kosugiEnd"] = "Kaçmak için minibüse git veya daha fazla ganimet almak istiyorsan kal.",
["hud_heist_kosugiEnd_hl"] = "Kaçış hazır!",
["hud_heist_kosugi_hl"] = "Depoyu yağmala",
["hud_heist_mad_01"] = "Uçağın gelip EMP'yi bırakabilmesi için uçaksavar sistemini devre dışı bırak.",
["hud_heist_mad_01_hl"] = "Uçaksavar sistemini bul ve devre dışı bırak",
["hud_heist_mad_02"] = "EMP'nin bırakıldığı kereste sahasına gir.",
["hud_heist_mad_02_hl"] = "Kereste fabrikasına gir",
["hud_heist_mad_03"] = "EMP’yi etkinleştirip koru; şarj olması zaman alacak",
["hud_heist_mad_03_hl"] = "EMP'yi etkinleştir",
["hud_heist_mad_04"] = "EMP, laboratuvarlara inen yolu açtı. Aşağı in!",
["hud_heist_mad_04_hl"] = "Laboratuvarlara in",
["hud_heist_mad_05"] = "Bir yerde denekleri taramak için kullanabileceğimiz bir tarayıcı olmalı. Bul.",
["hud_heist_mad_05_hl"] = "Tarayıcıyı bul",
["hud_heist_mad_06"] = "EMP denekleri bayılttı. Onları bulup tarayıcıya götür. Mavi giyimli olmalılar.",
["hud_heist_mad_06_hl"] = "Bir denek bulup tara",
["hud_heist_mad_07"] = "Paralı askerler denekleri taramanı istemiyor. Onları tarayıcıdan uzak tut!",
["hud_heist_mad_07_hl"] = "Tarayıcıyı koru",
["hud_heist_mad_08"] = "Biraz bilgi aldık ama dayanabilirsen daha fazlası işimize yarar. Daha fazla tara veya sunucuyu alıp ayrıl.",
["hud_heist_mad_08_hl"] = "Daha fazla tara veya sunucuyu al",
["hud_heist_mad_09"] = "Gereken bütün bilgiler elimizde. Sunucuyu al, gidelim!",
["hud_heist_mad_09_hl"] = "Sunucuyu al",
["hud_heist_mad_10"] = "Tamam beyler, burada olduğu söylenen bir evrak çantası da lazım. Onu bulun!",
["hud_heist_mad_10_hl"] = "Evrak çantasını bul",
["hud_heist_mad_11"] = "Sunucuyu ve evrak çantasını uçağa getir",
["hud_heist_mad_11_hl"] = "Sunucuyu güvenceye al",
["hud_heist_mad_12"] = "Buradan çık ve uçağa git!",
["hud_heist_mad_12_hl"] = "Kaçış",
["hud_heist_mad_13"] = "Gazın nereden verildiğini bulup durdur",
["hud_heist_mad_13_hl"] = "Gazı durdur",
["hud_heist_mad_14"] = "Tarayıcıda ek bir güvenlik adımı var. Baş bilim insanının elini kullanarak onay vermeliyiz. Onu bul!",
["hud_heist_mad_14_hl"] = "Başbilim insanının eliyle doğrulama yap",
["hud_heist_mad_16"] = "Duvar yolumuzu kapatıyor. Sistemini kırdığımız uçaksavar füzelerini kullanıp onu patlat!",
["hud_heist_mad_16_hl"] = "Duvarı patlat",
["hud_heist_man1"] = "Taxman’in peşinde olduğumuz sunucuyu göstermesini bekle. Gördüğünde onu korkutup limuzinine sok; hem sunucu hem de Taxman gerekiyor. Alex onu sokaktan vinçle yanımıza çıkaracak. Şansını artırmak için kullanabileceğin şeylere de gözünü açık tut.",
["hud_heist_man10"] = "Bilgisayarın işlemi sürdürdüğünden emin ol. Polislerin elektriği kesmesine izin verme. Keserlerse bilgisayarların çalışması için elektriği hemen geri aç.",
["hud_heist_man10_hl"] = "Bilgisayarı çalışır tut",
["hud_heist_man11"] = "Kaçışa geç; bir helikopter seni yandaki çatıdan alacak.",
["hud_heist_man11_hl"] = "Kaçış",
["hud_heist_man12"] = "Bain parayı aktarmaya hazır; son adımı yap ve aktarımı tamamla!",
["hud_heist_man12_hl"] = "Sistem kırmayı tamamla",
["hud_heist_man13"] = "Kafasına bir tane indirip koltuğa bağla!",
["hud_heist_man13_hl"] = "Taxman'i koltuğa bağla",
["hud_heist_man14"] = "Alex, vinçle limuzini açık sokaktan kaldırıp binanın üstüne taşıyor.",
["hud_heist_man14_hl"] = "Vinci bekle",
["hud_heist_man1_hl"] = "Hazırlıklar",
["hud_heist_man2"] = "Onlara saldırmadan önce sunucunun ortaya çıkmasını bekleyin! Para aktarımımızın tek yolu o sunucu!",
["hud_heist_man2_hl"] = "Alışveriş yapılıyor",
["hud_heist_man3"] = "Limuzine bak; Taxman’i dışarı çıkarabilir misin, gör.",
["hud_heist_man3_hl"] = "Limuzini kontrol et",
["hud_heist_man4"] = "Limuzini tutan kablolara ateş ederek onu düşür!",
["hud_heist_man4_hl"] = "Limuzini serbest bırak",
["hud_heist_man5"] = "Taxman’i limuzinden çıkar! Tavanı testereyle açıp dışarı al!",
["hud_heist_man5_hl"] = "Limuzini testereyle aç",
["hud_heist_man6"] = "Taxman'i başladığımız aktarım odasına götürmeliyiz. İş birliği yapması için gereken her türlü gücü kullan.",
["hud_heist_man6_hl"] = "Taxman’i aktarım odasına götür",
["hud_heist_man7"] = "Sunucuyu limuzinden al, aktarım odasına gidip bağla.",
["hud_heist_man7_hl"] = "Sunucuyu alıp bağla",
["hud_heist_man8"] = "Yönetici şifrelerini Taxman’den al! Bağır, tehdit et, eski usul güzel bir dayak at; her şey serbest, acelemiz var!",
["hud_heist_man8_hl"] = "Şifreleri al",
["hud_heist_man9"] = "Bain'in zekâsı, Taxman'in içeriden bilgisi ve ekibin ikna gücüyle IRS veri tabanına girip yüklü bir vergi indirimi elde et.",
["hud_heist_man9_hl"] = "IRS sisteminin kırılmasını bekle",
["hud_heist_man_mission1"] = "Yap.",
["hud_heist_man_mission1_hl"] = "Biraz PAYDAY kazan.",
["hud_heist_mex1"] = "Dışarıda bir yerde Meksika’ya giden yer altı tünelini bul.",
["hud_heist_mex10"] = "Uçak yakıtı tankı ve bir pompa bul. İkisini de uçağa bağla.",
["hud_heist_mex10_hl"] = "Yakıt hortumunu uçağa bağla",
["hud_heist_mex11"] = "Uçağı çalarak kaç.",
["hud_heist_mex11_hl"] = "Kaçış Mümkün",
