["hud_heist_mex13"] = "Yerleşkedeki paraları bul ve çal.",
["hud_heist_mex13_hl"] = "Para çal",
["hud_heist_mex14"] = "Hangarlardan birindeki uçağı bul.",
["hud_heist_mex14_hl"] = "Kaçış uçağını bul",
["hud_heist_mex15"] = "Kırmızı benzin bidonlarını bulup pompanın jeneratörüne yakıt doldur.",
["hud_heist_mex15_hl"] = "Jeneratöre yakıt doldur",
["hud_heist_mex16"] = "Yerleşkenin içindeki uçak anahtarlarını bul.",
["hud_heist_mex16_hl"] = "Uçağın anahtarlarını bul",
