["hud_heist_mex3_hl"] = "Şifreyi bul ve gir",
["hud_heist_mex4"] = "Motosikletçilerin kapı patlayıcılarını nerede sakladığını bul.",
["hud_heist_mex4_hl"] = "Kapı patlayıcılarını bul",
["hud_heist_mex5"] = "Kapı patlatma yüklerini tünel girişine yerleştir.",
["hud_heist_mex5_hl"] = "Kapı patlayıcılarını kur",
["hud_heist_mex6"] = "Kapı patlayıcılarını patlatmak için geri sayımı başlat.",
["hud_heist_mex6_hl"] = "Fünyeyi kur",
["hud_heist_mex7"] = "Murkywater askerlerinin fünyeyi devre dışı bırakmasını engelle.",
["hud_heist_mex7_hl"] = "Fünyeyi savun",
["hud_heist_mex8"] = "Sınırın diğer tarafına geçmek için tüneli kullan.",
["hud_heist_mex8_hl"] = "Tünelden Meksika'ya git",
