["hud_heist_mex9_hl"] = "Silahları çal",
["hud_heist_mia_mission1"] = "Motelde buluş.",
["hud_heist_mia_mission10"] = "Commissar’ın tam adresini bul. İpucu, harita, beyaz tahta ve diğer yararlı bilgiler için bodrumu ara. Bilgileri semt adına göre birleştir. Bain doğru semt adını sana tekrarlar.",
["hud_heist_mia_mission10_hl"] = "Doğru adresi ara",
