["hud_heist_mia_mission11_hl"] = "Kaç!",
["hud_heist_mia_mission12"] = "Sevkiyat sandıklarından çıkmak için maskeni tak.",
["hud_heist_mia_mission12_hl"] = "Maskeni tak",
["hud_heist_mia_mission13"] = "Commissar'ı yakalamak için dairelerde savaşarak ilerle!",
["hud_heist_mia_mission13_hl"] = "Commissar’ın peşine düş",
["hud_heist_mia_mission14"] = "Commissar'ın işini bitir.",
["hud_heist_mia_mission14_hl"] = "Commissar'ı öldür",
["hud_heist_mia_mission15"] = "Moteli arayıp Commissar’ın adamlarını öldür.",
["hud_heist_mia_mission15_hl"] = "Rus mafyacıları ortadan kaldır",
["hud_heist_mia_mission16"] = "Yönlendirilmiş Patlayıcılarla apartman girişini patlat.",
["hud_heist_mia_mission16_hl"] = "Girişi zorla aç",
["hud_heist_mia_mission17"] = "Kaçış aracı yolda. Gelene kadar hayatta kal!",
["hud_heist_mia_mission17_hl"] = "Helikopteri bekle",
["hud_heist_mia_mission18"] = "Termal matkabın kasa dairesinin kapısını açmasını bekle.",
["hud_heist_mia_mission18_hl"] = "Matkabı savun",
["hud_heist_mia_mission19"] = "Commissar özel hattan Bain’i arayacak. Bain böylece konumunu izleyip tam olarak nerede saklandığını bulabilir.",
["hud_heist_mia_mission19_hl"] = "Bain'in Commissar'ın aramasını izlemesini bekle",
["hud_heist_mia_mission1_hl"] = "Motele ilerle",
["hud_heist_mia_mission2"] = "Otoparktaki arabaları benzinle yak. Bidonu yerleştirdikten sonra ateş et.",
["hud_heist_mia_mission20"] = "Kapıyı açmak için ondan çıkan kabloyu kontrol et.",
["hud_heist_mia_mission20_hl"] = "Güçlendirilmiş kapıyı açmanın bir yolunu bul",
["hud_heist_mia_mission21"] = "Bile sana bir termal matkap bırakacak.",
["hud_heist_mia_mission21_hl"] = "Termal matkabı bekle",
["hud_heist_mia_mission22"] = "Helikopterin bıraktığı matkabı alıp kasa dairesinin kapısına monte et.",
["hud_heist_mia_mission22_hl"] = "Termal matkabı alıp kasa dairesine yerleştir",
["hud_heist_mia_mission23"] = "Ek ganimeti güvenceye almak ve apartman binasından kaçmak için helikopteri kullan.",
["hud_heist_mia_mission23_hl"] = "Ek ganimeti güvenceye alıp kaç!",
["hud_heist_mia_mission2_hl"] = "Arabaları ateşe ver",
["hud_heist_mia_mission3"] = "Benzin bidonları bul. Büyük ihtimalle benzin istasyonunun çevresindeler.",
["hud_heist_mia_mission3_hl"] = "Biraz benzin bul",
["hud_heist_mia_mission4"] = "Arabadaki C4'ü al ve benzin istasyonunun pompalarına yerleştir.",
["hud_heist_mia_mission4_hl"] = "Benzin istasyonunu yok et",
["hud_heist_mia_mission5"] = "Bodrum girişini bulmak için motelin alt kattaki odalarını araştır.",
["hud_heist_mia_mission5_hl"] = "Bodrum ara",
["hud_heist_mia_mission6"] = "Helikopter pilotunu bekle. Sana yardımcı olacak bir şey bırakacak.",
["hud_heist_mia_mission6_hl"] = "Bile'ın hediyeyi bırakmasını bekle",
["hud_heist_mia_mission7"] = "Kalın kabloyu kamyonete ve kapağa bağla, ardından kamyoneti çalıştır.",
["hud_heist_mia_mission7_hl"] = "Kapağı zorla aç",
