["hud_heist_moon_01"] = "Santa’yı, yani Vlad’ın sarhoş kayınbiraderini bulup kurtar. Alışveriş merkezinde bir yerde olmalı.",
["hud_heist_moon_01_hl"] = "Santa'yı kurtar",
["hud_heist_moon_03"] = "Birinci kattaki kuyumcuyu bul ve içeri gir.",
["hud_heist_moon_03_hl"] = "Kuyumcuya gir",
["hud_heist_moon_04"] = "Kurşungeçirmez cam vitrini devre dışı bırakmak için bilgisayardan tuş takımının sistemini kır.",
["hud_heist_moon_04_hl"] = "Tuş takımının sistemini kır",
["hud_heist_moon_05"] = "Kurşungeçirmez camın arkasındaki kolyeyi al ve Vlad için güvenceye al!",
["hud_heist_moon_05_hl"] = "Kolyeyi çal",
["hud_heist_moon_06"] = "Zemin kattaki oyuncak mağazasını bul ve içeri gir.",
["hud_heist_moon_06_hl"] = "Oyuncak mağazasına gir",
["hud_heist_moon_07"] = "Teneke oyuncağın bulunduğu alışveriş poşetini bulmak için AVM'yi ara. Poşetler mağazaların çeşitli yerlerinde olmalı.",
["hud_heist_moon_07_hl"] = "Oyuncağın olduğu alışveriş poşetini bul",
["hud_heist_moon_08"] = "Bile’ın helikopterle çatıya C4 bırakması için çatıda işaret fişeği yak.",
["hud_heist_moon_08_hl"] = "Helikopter pilotuna işaret fişeğiyle işaret ver",
["hud_heist_moon_09"] = "Birinci kattaki ayakkabı mağazasını bulup gir.",
["hud_heist_moon_09_hl"] = "Ayakkabı mağazasına gir",
["hud_heist_moon_10"] = "Ayakkabıların stokta olup olmadığını bilgisayardan kontrol et.",
["hud_heist_moon_10_hl"] = "Mağaza veri tabanını ara",
["hud_heist_moon_11"] = "Kapıdan geçip arka ofise gir!",
["hud_heist_moon_11_hl"] = "Arka ofise gir",
["hud_heist_moon_12"] = "Ayakkabıları alıp Noel ağacının yanına getir!",
["hud_heist_moon_12_hl"] = "Ayakkabıları çal",
["hud_heist_moon_13"] = "Helikopterin çatıya C4 bırakmasını bekle!",
["hud_heist_moon_13_hl"] = "C4'ün çatıya bırakılmasını bekle",
["hud_heist_moon_14"] = "Paketleri güvenceye almak için ağacın altına at!",
["hud_heist_moon_14_hl"] = "Vlad’ın paketlerini ağacın altında güvenceye al",
["hud_heist_moon_15"] = "Uçurabilmek için bütün C4’leri cam kubbenin çevresine yerleştir!",
["hud_heist_moon_15_hl"] = "C4'ü al ve kubbenin çevresine yerleştir",
["hud_heist_moon_16"] = "Helikopterin ağacı kaldırabilmesi için kabloları ağaca bağla!",
["hud_heist_moon_16_hl"] = "Kabloları Noel ağacına bağla",
["hud_heist_moon_17"] = "Noel ağacının çevresinde toplanıp kaç!",
["hud_heist_moon_17_hl"] = "Kaçış Mümkün",
["hud_heist_moon_18"] = "Ayakkabı mağazasının arkasındaki depo alanına eriş!",
["hud_heist_moon_18_hl"] = "Depo alanına git",
["hud_heist_moon_19"] = "Zemin kattaki teknoloji mağazasını bulup içeri gir.",
["hud_heist_moon_19_hl"] = "Teknoloji mağazasına gir",
["hud_heist_moon_21"] = "VR başlığına ulaşmak için tezgâhın yanındaki kasayı aç.",
