["hud_heist_nail_3_hl"] = "Doğru malzemeyi ekle",
["hud_heist_nail_4"] = "Bu parti hazır. Bir parti daha pişirmek istiyorsan biraz daha efedrin hapı ekle. Yoksa battaniyeyle örtülü varilin üstünde yakılmaya hazır bir işaret fişeği var. Kaçış aracı gelip seni almak için sinyali bekliyor.",
["hud_heist_nail_4_hl"] = "Daha fazla pişir veya kaç",
