["hud_heist_pent01"] = "İçeri girmenin iki yolu var. Metal dedektörlerini kapat veya ofisten geçmenin yolunu bul.",
["hud_heist_pent01_hl"] = "Sız ve asansörleri bul",
["hud_heist_pent02"] = "Operatörün binanın güvenlik sistemlerine erişmesi gerekiyor. Yeşil ışıklı güvenlik kutularını kapat.",
["hud_heist_pent02_hl"] = "Operatöre güvenlik erişimi ver",
["hud_heist_pent03"] = "Bodruma git ve asansörü aşağı çağır.",
["hud_heist_pent03_hl"] = "Bodrumdan asansörü çağır",
["hud_heist_pent04"] = "Binanın tepesine çelik halatla çıkarken asansör boşluğunun açık kalması için asansörün elektriğini kes.",
["hud_heist_pent04_hl"] = "Asansörün elektriğini kes",
