["hud_heist_pent05_hl"] = "Asansör boşluğuna eriş",
["hud_heist_pent06"] = "İçerideki bağlantımız temizlik platformunun kontrollerine erişebiliyor. Pencerenin yanındaki ışığı aç; platformu senin için indirecek.",
["hud_heist_pent06_hl"] = "Cam temizleme asansörüne ulaş",
