["hud_heist_pent07_hl"] = "Gizli sunucu odasını bul",
["hud_heist_pent08"] = "Kapının şifresi çatı katında bir yerde bir notta olmalı.",
["hud_heist_pent08_hl"] = "Şifreyi bulup sabit diski çal",
["hud_heist_pent10"] = "Triad, karargâhından dışarı sinyal gönderen alarm sistemlerine sıcak bakmıyor. Bu yüzden yangın alarmı itfaiyeye bağlı değil. Toplantıdakileri dışarı çekmek için alarmı çalıştır.",
["hud_heist_pent10_hl"] = "Yangın alarmını çalıştır",
