["hud_heist_pent14"] = "Triad lideri çatı katına altın gizlemiş; bul ve güvenceye al.",
["hud_heist_pent14_hl"] = "Gizli odaya eriş",
["hud_heist_pent15"] = "Sabit disk şifreli; erişmemiz aylar sürer. Şifresini çözmek için Yufu Wang’ın dizüstü bilgisayarını bul. Bitince diski mutfak asansörüyle aşağı gönder.",
["hud_heist_pent15_hl"] = "Belleğin şifresini çöz ve güvenceye al",
