["hud_heist_pent17_hl"] = "Asansörü yeniden çalıştır ve çağır",
["hud_heist_pent18"] = "Asansörün üst kapağını çıkar. Jeneratör odasından kabloyu alıp asansörü kapıya bağla. Sonra asansör kablosunu ateş ederek kopar.",
["hud_heist_pent18_hl"] = "Çatı katının kapısını zorla aç",
["hud_heist_pent19"] = "Sunucu odasına açılan kapıyı zorla aç. İçeri girince sabit diski çal. ",
["hud_heist_pent19_hl"] = "Sabit diski çal",
["hud_heist_pent20"] = "Yufu Wang'ı öldürmek için toplantı odasına girmeliyiz. Kapıyı arabayla kır.",
["hud_heist_pent20_hl"] = "Arabayı yerine getir",
["hud_heist_pent21"] = "İçerideki bağlantımız arabanın bagajına benzin ve aletler koydu. Arabayı toplantı odasının kapısını kırmaya hazırla.",
["hud_heist_pent21_hl"] = "Arabayı hazırla ve yakıt doldur",
["hud_heist_pent22"] = "Araba anahtarları küçük bir kasada kilitli. Yakındaki odalarda kasayı ara.",
["hud_heist_pent22_hl"] = "Anahtarları bul ve arabayı çalıştır",
["hud_heist_pent23"] = "Tekerlekler dönerken krikoyu indir; araba son hızla kapıya çarpsın.",
["hud_heist_pent23_hl"] = "Krikoyu indir",
["hud_heist_pent24"] = "Yufu Wang çatıya kaçtı. Onu takip edip etkisiz hâle getir.",
["hud_heist_pent24_hl"] = "Triad liderini öldür",
