["hud_heist_shoutout_raid3"] = "Kasa dairesini açmanın bir yolunu bul. Havalandırma fanlarına Levye sıkıştırabilirsin. Bu, soğutma sistemini etkileyip otomatik acil durum önlemini devreye sokar. Levyeler depoda bulunabilir.",
