["hud_heist_shoutout_raid4_hl"] = "Kasa dairesinin aşırı ısınmasını bekle",
["hud_heist_shoutout_raid5"] = "Nükleer savaş başlıklarını eski rıhtımdaki Vlad’ın trenine taşı.",
["hud_heist_shoutout_raid5_hl"] = "Savaş başlıklarını trene teslim et",
["hud_heist_shoutout_raid6"] = "Kaçmak için trene atla. Depoda daha fazla ganimet de var.",
