["hud_heist_shoutout_raid7"] = "Trene atlayıp kaç.",
["hud_heist_shoutout_raid7_hl"] = "Kaç!",
["hud_heist_shoutout_raid_hl"] = "Rıhtımdaki o tekinsiz eski depoyu hatırlıyor musunuz? Murkywater’ın ganimet kaçırdığı yeri? İşte oraya dönüyoruz.",
