["hud_heist_tag02_hl"] = "Beyaz tahtayı bul",
["hud_heist_tag03"] = "Güvenlik bariyerinin paneline erişmek için doğru dizüstü bilgisayarın sistemini kır. Sonrasında bariyeri açmak için sınırlı zamanın olacak; acele et!",
