["loading_gameplay_1"] = "Sözleşme Aracısını dinle; sırada ne yapman gerektiğini sana söyler.",
["loading_gameplay_10"] = "Başarı ekranında, hayatta kalan her ekip üyesi için bonus kazanırsın.",
["loading_gameplay_100"] = "Yaydan attığın her okun hasarı, atışı ne kadar uzun süre hazırladığına bağlı olarak artar.",
["loading_gameplay_101"] = "Şok bombaları yere düştükten sonra ateş edilerek, hatta Yakın Dövüş Silahıyla vurularak yok edilebilir.",
["loading_gameplay_102"] = "Bazı kapıları kilitlerine ateş ederek açabilirsin.",
["loading_gameplay_103"] = "Keşif Modunda da, özellikle muhafızlara çarparsan tespit edilebilirsin. Ancak muhafızların seni fark etmeye başladığı mesafe çok daha kısadır.",
["loading_gameplay_104"] = "Siviller kırık kameraları veya ganimet çantalarını fark etmez. Ancak Ceset Torbalarını fark ederler.",
["loading_gameplay_105"] = "Ceset Torbalarını güvenle saklamak için derin suya veya çöp konteynerlerine atabilirsin.",
["loading_gameplay_106"] = "Polisler, henüz çantalanmamış ganimetleri geri almaya çalışmaz.",
["loading_gameplay_107"] = "Lazerler sana hasar vermez ama alarmı tetikler.",
["loading_gameplay_108"] = "ECM Karıştırıcılar muhafızların alarm vermesini önleyebilir. Ancak etkinken haritadaki bazı hedeflerin tamamlanmasını da engelleyebilirler. Bu yüzden onları son çare olarak kullan.",
["loading_gameplay_109"] = "ECM Karıştırıcılar, SWAT minibüsü taretlerini geçici olarak kendi tarafına geçirir.",
["loading_gameplay_11"] = "Düşük Tespit Riski, Hayalet Beceri Ağacıyla çatışmada da işe yarayabilir. Birinin zırh giymemesi, çatışmada kendini savunamayacağı anlamına gelmez.",
["loading_gameplay_110"] = "ECM Karıştırıcıların geri besleme işlevi her 4 dakikada bir yenilenir.",
["loading_gameplay_111"] = "\"Yakın Dövüş\" tuşunu basılı tutarak Yakın Dövüş Silahını daha güçlü bir saldırıya hazırlayabilirsin.",
["loading_gameplay_112"] = "Bazı düşmanlar vücut zırhı kullanır. Kafalarına nişan almalısın.",
["loading_gameplay_113"] = "SWAT minibüsü taretleri, kalkanları her kırıldığında birer kez olmak üzere, kendilerini iki kez onarır.",
["loading_gameplay_114"] = "SWAT minibüsü taretinin zayıf noktası, silahın altındaki yansıtıcı kameradır. En fazla hasarı vermek için oraya nişan al.",
["loading_gameplay_115"] = "Çoğu pencerenin kilidi açılabilir. Camı kırmak çok gürültü çıkarır. Kırık cam gören siviller bile şüphelenir.",
["loading_gameplay_116"] = "Bir pencereyi kırarsan, geçen muhafızları ve sivilleri kandırmak için onu kapatacak tahtalar bulmaya çalış.",
["loading_gameplay_117"] = "Susturuculu testereler bile biraz ses çıkarır. Yakındaki insanlara dikkat et.",
["loading_gameplay_118"] = "Bağlanmamış siviller gözetimsiz kalırsa ayağa kalkıp kaçar. Bunu önlemek için Plastik Kelepçelerini kullan.",
["loading_gameplay_119"] = "Ace of Spades fırlatılabiliri sessizdir. El bombaları ise değildir. Gizlice ilerleyeceksen hazırlığını buna göre yap.",
["loading_gameplay_12"] = "Düşmanını tanı. Cloaker birimleri, yeşil parlayan belirgin gece görüş gözlükleri takar ve üzerine hücum ederken ses çıkarır. Bölgeye geldiklerinde de bir parazit sesi duyabilirsin.",
["loading_gameplay_120"] = "ECM Karıştırıcılar kameraları geçici olarak devre dışı bırakır. Zor durumda kaldığında kamera operatörünü kör etmek için kullanmaktan çekinme.",
["loading_gameplay_121"] = "Kameralar ses algılayamaz; ancak şüpheli bir hareketi uzun süre görürlerse alarm verirler.",
["loading_gameplay_122"] = "Bir kamera şüpheli bir hareket görürse alarmın önüne geçemezsin.",
["loading_gameplay_123"] = "Yakın Dövüş Silahları her zaman sessizdir. Susturucun yoksa sessizce düşman indirmek için en iyi dostun onlardır.",
["loading_gameplay_124"] = "Muhafızlara fazla yaklaşırsan arkalarında olduğunu anlarlar. Onları takip ederken biraz mesafe bırak.",
["loading_gameplay_125"] = "Çoğu silahın şarjörü, içinde hâlâ mermi varken daha hızlı değiştirilir.",
["loading_gameplay_126"] = "Captain Winters bölgede olduğu sürece polis saldırısı durmaz.",
["loading_gameplay_127"] = "Silahın \"Tehdit\" istatistiği, ateş ettiğinde polislerin ateşten kaçınıp siper arama ihtimalini gösterir. Değer yükseldikçe silahın her atışı daha tehditkâr olur",
["loading_gameplay_128"] = "Neredeyse tüm matkapların kendiliğinden bozulma ihtimali vardır. Gözünü üzerlerinden ayırma.",
["loading_gameplay_129"] = "Teçhizat veya Ön Planlama ekranından destek satın almak soygunda çok işe yarayabilir. Seçenekleri dikkatle incele.",
["loading_gameplay_13"] = "Düşmanını tanı. Medic, parlak kırmızı kıyafetler giyer ve kalabalık içinde kolayca tanınabilir.",
["loading_gameplay_130"] = "Bir ekip arkadaşın yere düştüğünde, onu kaldırırken ekibin geri kalanından seni korumasını iste.",
["loading_gameplay_131"] = "Kapıları ve kiralık kasaları testereyle kesmek, onları açmanın en hızlı yoludur ama çok gürültülüdür. Gürültüyü azaltmak için sessiz motoru kullan.",
["loading_gameplay_132"] = "Çanta taşırken daha kolay tespit edilirsin.",
["loading_gameplay_133"] = "Rehineler can simidindir. Onları kontrol altında, çatışmadan ve polislerden uzakta tut.",
["loading_gameplay_134"] = "Tuzak Mayınları her yere yerleştirilebilir. Cloaker birimlerinin çıktığı havalandırmalar veya polislerin girmesini istemediğin bir oda buna örnektir.",
["loading_gameplay_135"] = "Polislere El Bombası atarken dikkatli ol. Bombayı havadayken kolayca vurabilirler.",
["loading_gameplay_136"] = "Öldürdüğün her sivil, Bain seni çıkarmaya çalışırken gözaltında geçireceğin süreyi uzatır.",
["loading_gameplay_137"] = "Cloaker birimleri, ECM geri beslemesinden etkilenmez.",
["loading_gameplay_138"] = "Ayakta kalan son kişiysen hayatta kalman, hedefi tamamlamaktan çok daha önemlidir.",
["loading_gameplay_139"] = "Pompalı Tüfekler tek atışta birden fazla polisi indirebilir. Kalabalığa nişan al ve ateş et.",
["loading_gameplay_14"] = "Düşmanını tanı. İki farklı Shield birimi bulunur. Bazıları ışık ve Hafif Makineli Silah taşırken diğerleri Tabanca taşır.",
["loading_gameplay_140"] = "Keskin Nişancı Tüfekleri, Shield kalkanlarını ve zırhları, hatta birden fazla düşmanı delip geçebilir.",
["loading_gameplay_141"] = "Ayakta durursan düşmanlar seni uzaktan görür. Görüşlerinden uzak kalmak için çömel.",
["loading_gameplay_15"] = "Düşmanını tanı. ZEAL birimlerinin hepsi şehir kamuflajı giyer. Bu yüzden hangisinde ek zırh olduğunu anlamak daha zordur.",
["loading_gameplay_16"] = "Düşmanını tanı. Taser birimleri, koyu mavi ve sarı zırhlarından tanınır.",
["loading_gameplay_17"] = "Düşmanını tanı. Keskin nişancılar, lazer nişangâhlarıyla yerlerini belli eder.",
["loading_gameplay_18"] = "Düşmanını tanı. SWAT tareti, kocaman bir SWAT minibüsüne bağlı olmasından tanınır.",
["loading_gameplay_19"] = "Avantaj Desteleri oynayışını kökten değiştirebilir. Tarzına uygun olanı seç.",
["loading_gameplay_2"] = "Mühimmatın mı azalıyor? Yere bak; ölen polisler mühimmat kutusu düşürür.",
["loading_gameplay_20"] = "Sıhhiyeci Beceri Dalı, seni ve soyguncu arkadaşlarını sağlıklı ve hayatta tutmaya odaklanır.",
["loading_gameplay_21"] = "Rehine Uzmanı Beceri Dalı, polisler dahil olmak üzere rehineleri ele geçirmeye ve kontrol etmeye odaklanır.",
["loading_gameplay_22"] = "Keskin Nişancı Beceri Dalı, tek ve isabetli atışlarla nişancılıkta uzmanlaşır.",
["loading_gameplay_23"] = "Pompalı Ustası Beceri Dalı, Pompalı Tüfek kullanırken büyük bonuslar sağlar.",
["loading_gameplay_24"] = "Tank Beceri Dalı seni daha güçlü ve dayanıklı kılar.",
["loading_gameplay_25"] = "Mühimmat Uzmanı Beceri Dalı, mühimmata odaklanır. OVE9000 Saw için geliştirmeler de içerir.",
["loading_gameplay_26"] = "Mühendis Beceri Dalı, ağırlıklı olarak Otomatik Taret kullanımına odaklanır.",
["loading_gameplay_27"] = "Gedikaçıcı Beceri Dalı, kapıları, kasaları ve kasa dairelerini hızla açmaya odaklanır. Tuzak Mayınlarını da geliştirir.",
