["loading_trivia_34"] = "Dallas dişçiye gitmeyi sevmez.",
["loading_trivia_35"] = "Wolf, elektrikli aletlere servet harcar.",
["loading_trivia_36"] = "Wolf eskiden İsveç'te oyun geliştiricisi olarak çalışıyordu.",
["loading_trivia_37"] = "Wolf sağlıklı bir insan değil.",
["loading_trivia_38"] = "Wolf rehinelere iyi davranmaz.",
["loading_trivia_39"] = "Bodhi sörf tahtalarına servet harcıyor.",
["loading_trivia_4"] = "Jimmy bir kez Bonnie’ye içki yarışmasında meydan okudu ama iş neredeyse şiddete varınca yarıda kesmek zorunda kaldılar.",
["loading_trivia_40"] = "Bodhi eskiden Ex-Presidents adlı bir çetenin üyesiydi.",
["loading_trivia_41"] = "Bodhi bu işi yalnızca para için yapmıyor.",
["loading_trivia_42"] = "Bodhi, ekstrem paraşüt atlayışı gibi çılgın gösterilere meraklıdır.",
["loading_trivia_43"] = "Chains silahlara servet harcıyor.",
["loading_trivia_44"] = "Chains eskiden askerdi ama oraya uyum sağlayamadı. Banka soygunculuğuna ise doğuştan yetenekli.",
["loading_trivia_45"] = "Chains genellikle kurşun işlemezmiş gibi davranıp konuşur. Belki de öyledir.",
["loading_trivia_46"] = "Chains’in başı bazen derde girer.",
["loading_trivia_47"] = "Clover elektroniğe servet harcıyor.",
["loading_trivia_48"] = "Clover ile Hoxton’ın, Payday Gang’den öncesine uzanan uzun ve karmaşık bir ilişkisi var. Ama artık iyi anlaşıyorlar.",
["loading_trivia_49"] = "Clover’ın adı şanslı bir soyguncu olmasına gönderme yapar. Gerçekten de şanslıdır.",
["loading_trivia_5"] = "Jimmy kokaine servet harcar.",
["loading_trivia_50"] = "Clover, The Walking Dead hayranıdır.",
["loading_trivia_51"] = "Houston arabalara servet harcıyor.",
["loading_trivia_52"] = "Houston’ın çok sorunu var ama polis bunlardan biri değil.",
["loading_trivia_53"] = "Houston, Hoxton'ın aptal olduğunu düşünüyor.",
["loading_trivia_54"] = "Houston, kaçış minibüsünü gözleyip iyi durumda olduğundan emin olmayı sever.",
["loading_trivia_55"] = "Bonnie viskiye servet harcar.",
["loading_trivia_56"] = "Bonnie eskiden balayı katiliydi; sigorta parası için evlenip kocalarını öldürürdü.",
["loading_trivia_57"] = "Bonnie bilgisayarlarda iyi değildir.",
["loading_trivia_58"] = "Bonnie muhtemelen fazla kumar oynuyor. Ama bunu ona söylemek pek güvenli olmaz.",
["loading_trivia_59"] = "Captain Winters koruyucu ekipmana servet harcıyor.",
["loading_trivia_6"] = "Jimmy, Güvenli Evin barını Aldstone’ın doldurabileceğinden hızlı boşaltacağını ilan etti. Sonucu belirsiz, devasa bir mücadele.",
["loading_trivia_60"] = "Captain Winters sevecen bir lider değildir.",
["loading_trivia_61"] = "Captain Winters, Payday Gang’e karşı kişisel bir kin besler.",
["loading_trivia_62"] = "Captain Winters, GenSec’e katılmadan önce askerî inzibatta görev yapıyordu.",
["loading_trivia_63"] = "Rust motosikletine servet harcar.",
["loading_trivia_64"] = "Rust, Payday Gang’e katılmak için güçlü bir kardeşliğe ihanet etti.",
["loading_trivia_65"] = "Overkill MC, Rust'ın ölüm emrini verdi.",
["loading_trivia_66"] = "Rust, motosikletine zarar veren herkesi muhtemelen öldürürdü.",
["loading_trivia_67"] = "Sokol buz hokeyi ekipmanına servet harcıyor.",
["loading_trivia_68"] = "Sokol her hafta Rus hokey ligini izler.",
["loading_trivia_69"] = "Sokol hâlâ profesyonel bir sporcunun fiziğine sahip.",
["loading_trivia_7"] = "Jacket, diğer soygunculara kasetçalarını kullanmadan tek kelime bile söylemedi.",
["loading_trivia_70"] = "Sokol, buz hokeyi günlerinden beri Rusya'da hâlâ hayranları olmasından hoşlanıyor.",
["loading_trivia_71"] = "Jiro, kılıç bakımına servet harcar.",
["loading_trivia_72"] = "Jiro’nun vücudu geleneksel Yakuza dövmeleriyle dolu.",
["loading_trivia_73"] = "Jiro, ABD’de birkaç yıl geçirdikten sonra İngilizcesini epey geliştirdi.",
["loading_trivia_74"] = "Jiro Amerikan yemeklerini beğenmekten çok onlara katlanıyor.",
["loading_trivia_75"] = "Dragan formda kalmaya çok zaman ayırır.",
["loading_trivia_76"] = "Dragan sağlıklı yiyeceklere servet harcar.",
["loading_trivia_77"] = "Dragan eskiden Hırvatistan’da polisti.",
["loading_trivia_78"] = "Dragan’ı Payday Gang ile The Butcher tanıştırdı.",
["loading_trivia_79"] = "Aldstone özel ithal çaya servet harcar.",
["loading_trivia_8"] = "Jacket pillere servet harcıyor.",
["loading_trivia_80"] = "Aldstone’ın adını, onu hiç kullanmayan Hoxton dışında hiçbir soyguncu bilmiyor.",
["loading_trivia_81"] = "Aldstone bir zamanlar evliydi ama sonu mutlu bitmedi.",
["loading_trivia_82"] = "Aldstone, Hoxton’ın meslek seçimini beğenmiyor ama sadık ve profesyonel bir uşak olarak bunu metanetle kabulleniyor.",
["loading_trivia_83"] = "Gage gümrük görevlilerine rüşvet vermeye servet harcıyor.",
["loading_trivia_84"] = "Gage işinin her yanını sevmese de sattığı mallara tutkuyla bağlıdır.",
["loading_trivia_85"] = "Gage çoğu zaman hafife alınır; bunu kendi lehine kullanır.",
["loading_trivia_86"] = "Gage'in dünya çapında geniş bir bağlantı ağı var; bu sayede en iyi donanımı temin edebiliyor.",
["loading_trivia_87"] = "Bob McKendrick nüfuz ticaretine servet harcıyor.",
["loading_trivia_88"] = "Bob McKendrick nice mücadeleden geçmiş, kariyerinde pek çok iniş çıkış yaşamış deneyimli bir siyasetçidir.",
["loading_trivia_89"] = "Bob McKendrick hafife alınacak biri değildir.",
["loading_trivia_9"] = "Jacket kendinden bahsetmeyi sevmez.",
["loading_trivia_90"] = "The Butcher'ın ailesi birkaç kuşaktır silah kaçakçılığı yapıyor.",
["loading_trivia_91"] = "The Butcher’ın imzası ve çalışma yöntemi, silahları donmuş hayvan karkaslarının içinde taşımaktır.",
["loading_trivia_92"] = "Jiro, Cloaker'ı sevmez. Katana'sıyla kafalarını keser.",
["loading_trivia_93"] = "Bodhi, Taser'lardan nefret eder. Onunla oynarken birini Platypus Sniper Rifle ile vurmayı dene.",
["loading_trivia_94"] = "Goat Simulator Heist yapılırken hiçbir hayvana zarar verilmedi.",
["loading_trivia_95"] = "Hector ciddi işler yapan bir adamdır. D.C.’deki operasyonlarının bozulmasından hoşlanmaz. Ondan uzun, çatışmalı soygunlar bekle.",
["loading_trivia_96"] = "Etkinlik soygunları, Cadılar Bayramı gibi özel etkinliklerde geçer. Çılgın şeylere hazır ol.",
["loading_trivia_97"] = "The Dentist’in işleri dikkatli planlama ve incelik ister. Hazır olduğunu düşünüyorsan onu ara.",
["loading_trivia_98"] = "Klasikler. Bunlar ekibin şimdiye dek yaptığı en büyük işlerdi. Hâlâ altından kalkabilecekler mi, bir bakalım mı?",
["loading_trivia_99"] = "Locke, Murkywater'ın açgözlü eski paralı askerlerinden biridir. Verdiği işler neredeyse her zaman eski işvereniyle ilgilidir.",
